### Python

```python
import sys
from bisect import bisect_left

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    T = data[idx]; idx += 1
    out_lines = []
    for _ in range(T):
        n = data[idx]; m = data[idx+1]; K = data[idx+2]
        idx += 3
        x = data[idx:idx+n]; idx += n
        y = data[idx:idx+m]; idx += m

        y.sort()
        ans = 0
        for xi in x:
            if K == 0:
                ans += m
            elif xi == 0:
                continue
            else:
                need = (K + xi - 1) // xi   # 向上取整
                pos = bisect_left(y, need)
                ans += m - pos
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

