import java.io.*;
import java.util.*;

public class Main {
    static long countPairs(int[] x, int[] y, long K) {
        Arrays.sort(y);
        int m = y.length;
        long ans = 0;
        for (int xi : x) {
            if (K == 0) {
                ans += m;
            } else if (xi == 0) {
                continue;
            } else {
                long need = (K + xi - 1) / xi;   // 向上取整
                int pos = lowerBound(y, need);
                ans += m - pos;
            }
        }
        return ans;
    }

    static int lowerBound(int[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int T = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            int n = fs.nextInt();
